    if pointer == '':
        return obj
    if not pointer.startswith('/'):
        raise ValueError("Pointer must start with '/'")

    tokens = pointer[1:].split('/')
    current = obj

    for token in tokens:
        # Decode escapes
        key = token.replace('~1', '/').replace('~0', '~')

        if isinstance(current, dict):
            if key not in current:
                raise KeyError(f"Key '{key}' not found")
            current = current[key]
        elif isinstance(current, list):
            try:
                idx = int(key)
            except ValueError:
                raise KeyError(f"Token '{token}' is not a valid index for a list")

            if idx < 0 or idx >= len(current):
                raise KeyError(f"Index {idx} out of range")
            current = current[idx]
        else:
            # Cannot descend into non-container types with remaining path
            raise KeyError(f"Cannot index into {type(current).__name__}")

    return current
